const i = $json;
const q = (s, tag) => String(s == null ? '' : s).split(tag).join('');
const et = (i.entity_type || '').replace(/[^a-z_]/gi, '');
const entitySql = et ? `'${et}'` : 'null';
const eid = (i.entity_id || '').match(/^[0-9a-f-]{36}$/i) ? `'${i.entity_id}'::uuid` : 'null';
const sql = `insert into documents(title, source_type, source_uri, entity_type, entity_id, checksum, status) values ($t$${q(i.title,'$t$')}$t$, $st$${q(i.source_type,'$st$')}$st$, $su$${q(i.source_uri,'$su$')}$su$, ${entitySql}, ${eid}, md5($tx$${q(i.text,'$tx$')}$tx$), 'chunked') on conflict (checksum) where checksum is not null do update set status='chunked' returning id as document_id;`;
return [{ json: { sql } }];

const text = $('Appel (Execute Workflow)').item.json.text || '';
const docId = $json.document_id;
const parts = text.split(/\n\n+/);
const chunks = []; let buf = '';
for (const p of parts) {
  if ((buf + '\n\n' + p).length > 800 && buf) { chunks.push(buf); buf = p; }
  else { buf = buf ? buf + '\n\n' + p : p; }
}
if (buf) chunks.push(buf);
return chunks.map((c, idx) => ({ json: { document_id: docId, chunk_index: idx, content: c } }));

const ch = $('Découper en chunks').item.json;
const emb = ($json.data[0].embedding || []).join(',');
const content = String(ch.content || '').split('$c$').join('');
const sql = `insert into document_chunks(document_id, chunk_index, content, embedding) values ('${ch.document_id}'::uuid, ${parseInt(ch.chunk_index,10)}, $c$${content}$c$, '[${emb}]'::vector) on conflict (document_id, chunk_index) do update set content=excluded.content, embedding=excluded.embedding;`;
return [{ json: { sql } }];
